package com.group49.support.servlet;
import com.group49.support.dao.TicketDao;import com.group49.support.model.*;import com.group49.support.util.WebUtil;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.LocalDate;
@WebServlet("/reports") public class ReportServlet extends HttpServlet{private final TicketDao tickets=new TicketDao();private boolean allowed(User u){return u.hasRole("CUSTOMER_SUPPORT_MANAGER","OPERATIONS_EXECUTIVE","QUALITY_ASSURANCE_SUPERVISOR");}
 @Override protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=WebUtil.currentUser(req);if(!allowed(u)){res.sendError(403);return;}try{var list=tickets.list(u,WebUtil.value(req.getParameter("q")),WebUtil.value(req.getParameter("status")));if("csv".equals(req.getParameter("format"))){res.setContentType("text/csv;charset=UTF-8");res.setHeader("Content-Disposition","attachment; filename=ticket-report-"+LocalDate.now()+".csv");PrintWriter out=res.getWriter();out.println("Ticket Number,Customer,Category,Subject,Priority,Status,Assigned To,Created");for(Ticket t:list)out.printf("\"%s\",\"%s\",\"%s\",\"%s\",%s,%s,\"%s\",%s%n",clean(t.number()),clean(t.customerName()),clean(t.categoryName()),clean(t.subject()),t.priority(),t.status(),clean(t.assigneeName()),t.createdAt());return;}req.setAttribute("reportTickets",list);req.setAttribute("stats",tickets.stats(u,0));req.getRequestDispatcher("/WEB-INF/views/reports/index.jsp").forward(req,res);}catch(Exception e){throw new ServletException(e);}}
 private String clean(String value){return value==null?"":value.replace("\"","\"\"").replace("\r"," ").replace("\n"," ");}
}
